:root {
  --bg-card: #1a1a2e;
  --bg-header: #16213e;
  --bg-stat: #0d1b2a;
  --bg-highlight: #e94560;
  --bg-done: #1e3a2f;
  --bg-active: #2a1f0e;
  --bg-pending: #1c1c2e;
  --color-white: #f0f0f0;
  --color-muted: #8892a4;
  --color-accent: #e94560;
  --color-gold: #f5a623;
  --color-green: #2ecc71;
  --color-tyre-m: #f5a623;
  --color-tyre-text: #1a1a2e;
  --border-subtle: #2a3550;
  --fuel-track-bg: #0d1b2a;
  --fuel-fill-color: #e94560;
  --badge-done-bg: #2ecc71;
  --badge-done-text: #0d1b2a;
  --badge-active-bg: #f5a623;
  --badge-active-text: #1a1a2e;
  --badge-pending-bg: #3a3a5c;
  --badge-pending-text: #8892a4;
}

article.pit-card {
  background: var(--bg-card);
  border-radius: 12px;
  width: 460px;
  overflow: hidden;
  border: 1px solid var(--border-subtle);
}

.pit-header {
  background: var(--bg-header);
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 8px 12px;
  border-bottom: 1px solid var(--border-subtle);
}

.team-badge {
  display: flex;
  align-items: center;
  gap: 8px;
}

.team-num {
  background: var(--color-accent);
  color: var(--color-white);
  font-size: 18px;
  font-weight: 800;
  width: 36px;
  height: 36px;
  border-radius: 6px;
  display: flex;
  align-items: center;
  justify-content: center;
  letter-spacing: -1px;
}

.team-info {
  display: flex;
  flex-direction: column;
  gap: 1px;
}

.team-name {
  color: var(--color-white);
  font-size: 14px;
  font-weight: 700;
  line-height: 1.2;
}

.team-class {
  color: var(--color-muted);
  font-size: 10px;
  font-weight: 500;
  text-transform: uppercase;
  letter-spacing: 0.5px;
}

.race-status {
  display: flex;
  align-items: center;
  gap: 5px;
  border: 1px solid var(--color-accent);
  border-radius: 20px;
  padding: 3px 8px;
}

.status-dot {
  width: 6px;
  height: 6px;
  border-radius: 50%;
  background: var(--color-accent);
  flex-shrink: 0;
}

.status-label {
  color: var(--color-accent);
  font-size: 10px;
  font-weight: 700;
  letter-spacing: 0.5px;
}

.lap-stats {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 1px;
  background: var(--border-subtle);
  border-bottom: 1px solid var(--border-subtle);
}

.stat-block {
  background: var(--bg-stat);
  display: flex;
  flex-direction: column;
  align-items: center;
  padding: 7px 6px;
  gap: 2px;
}

.stat-block.highlight {
  background: var(--bg-highlight);
}

.stat-value {
  color: var(--color-white);
  font-size: 15px;
  font-weight: 800;
  line-height: 1;
}

.stat-block.highlight .stat-value {
  color: var(--color-white);
}

.stat-label {
  color: var(--color-muted);
  font-size: 9px;
  font-weight: 500;
  text-transform: uppercase;
  letter-spacing: 0.3px;
}

.stat-block.highlight .stat-label {
  color: rgba(240, 240, 240, 0.75);
}

.pit-strategy {
  padding: 8px 12px;
  border-bottom: 1px solid var(--border-subtle);
}

.section-title {
  color: var(--color-muted);
  font-size: 9px;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 1px;
  margin: 0 0 6px;
}

.stop-list {
  list-style: none;
  margin: 0;
  padding: 0;
  display: flex;
  flex-direction: column;
  gap: 4px;
}

.stop-item {
  display: flex;
  align-items: center;
  gap: 8px;
  padding: 5px 8px;
  border-radius: 6px;
  border: 1px solid var(--border-subtle);
}

.stop-item.done {
  background: var(--bg-done);
  border-color: var(--color-green);
}

.stop-item.active {
  background: var(--bg-active);
  border-color: var(--color-gold);
}

.stop-item.pending {
  background: var(--bg-pending);
}

.stop-icon {
  font-size: 12px;
  flex-shrink: 0;
}

.stop-detail {
  display: flex;
  flex-direction: column;
  gap: 1px;
  flex: 1;
}

.stop-name {
  color: var(--color-white);
  font-size: 12px;
  font-weight: 600;
  line-height: 1.2;
}

.stop-note {
  color: var(--color-muted);
  font-size: 10px;
  font-weight: 400;
}

.stop-badge {
  font-size: 9px;
  font-weight: 700;
  padding: 2px 6px;
  border-radius: 8px;
  text-transform: uppercase;
  letter-spacing: 0.5px;
  flex-shrink: 0;
}

.done-badge {
  background: var(--badge-done-bg);
  color: var(--badge-done-text);
}

.active-badge {
  background: var(--badge-active-bg);
  color: var(--badge-active-text);
}

.pending-badge {
  background: var(--badge-pending-bg);
  color: var(--badge-pending-text);
}

.pit-footer {
  padding: 7px 12px 9px;
  display: flex;
  flex-direction: column;
  gap: 5px;
}

.tyre-row {
  display: flex;
  align-items: center;
  gap: 8px;
}

.tyre-pill {
  width: 22px;
  height: 22px;
  border-radius: 50%;
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 11px;
  font-weight: 800;
  flex-shrink: 0;
}

.tyre-pill.medium {
  background: var(--color-tyre-m);
  color: var(--color-tyre-text);
}

.tyre-age {
  color: var(--color-muted);
  font-size: 11px;
}

.fuel-bar-wrap {
  display: flex;
  align-items: center;
  gap: 8px;
}

.fuel-label {
  color: var(--color-muted);
  font-size: 9px;
  font-weight: 600;
  text-transform: uppercase;
  letter-spacing: 0.5px;
  width: 28px;
  flex-shrink: 0;
}

.fuel-track {
  flex: 1;
  height: 7px;
  background: var(--fuel-track-bg);
  border-radius: 4px;
  overflow: hidden;
  border: 1px solid var(--border-subtle);
}

.fuel-fill {
  width: 63%;
  height: 100%;
  background: var(--fuel-fill-color);
  border-radius: 4px;
}

.fuel-pct {
  color: var(--color-white);
  font-size: 10px;
  font-weight: 700;
  width: 28px;
  text-align: right;
}
